def semver_sort(versions):
    def parse_version(v):
        # Split build metadata
        if '+' in v:
            v, build = v.split('+', 1)
        else:
            build = ''

        # Split pre-release
        if '-' in v:
            core, prerelease = v.split('-', 1)
        else:
            core = v
            prerelease = None

        # Parse core version
        parts = core.split('.')
        major = int(parts[0]) if len(parts) > 0 else 0
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease is not None:
            identifiers = prerelease.split('.')
            prerelease_parts = []
            for ident in identifiers:
                if ident.isdigit():
                    prerelease_parts.append((0, int(ident)))
                else:
                    prerelease_parts.append((1, ident))
        else:
            prerelease_parts = None

        return (major, minor, patch, prerelease_parts)

    def compare_key(v):
        major, minor, patch, prerelease_parts = parse_version(v)

        # For sorting: versions with pre-release sort before those without
        # We use (major, minor, patch, has_prerelease, prerelease_parts)
        # has_prerelease: 0 if has prerelease (sorts first), 1 if no prerelease
        if prerelease_parts is None:
            # No pre-release: sorts after same version with pre-release
            return (major, minor, patch, 1, ())
        else:
            # Has pre-release: sorts before same version without pre-release
            return (major, minor, patch, 0, tuple(prerelease_parts))

    # Sort using stable sort to preserve input order for equal precedence
    return sorted(versions, key=compare_key)

